from decimal import Decimal


class CurrencyMismatch(ValueError):
    """Raised when arithmetic mixes two different currencies."""


class Money:
    """An immutable amount of a single currency."""

    __slots__ = ("amount", "currency")

    # Number of minor-unit digits per currency.  Anything not listed is
    # assumed to use two decimals, which is the overwhelmingly common case.
    _DECIMALS = {
        "JPY": 0,
        "KRW": 0,
        "CLP": 0,
        "ISK": 0,
        "BHD": 3,
        "KWD": 3,
        "OMR": 3,
    }

    def __init__(self, amount=0, currency=None):
        # Accept another Money and copy it (helps with subclassing / converting).
        if isinstance(amount, Money):
            if currency is None:
                currency = amount.currency
            amount = amount.amount
        self.amount = self._to_decimal(amount)
        self.currency = currency

    # ------------------------------------------------------------------ #
    # conversion helpers
    # ------------------------------------------------------------------ #
    @staticmethod
    def _to_decimal(value):
        if isinstance(value, Decimal):
            return value
        if isinstance(value, float):
            # str() avoids dragging in the binary-float noise: str(0.1) == '0.1'.
            return Decimal(str(value))
        if isinstance(value, int):
            return Decimal(value)
        if isinstance(value, str):
            return Decimal(value.strip())
        # Anything else (e.g. another numeric type) is funnelled through str.
        return Decimal(str(value))

    def _decimals(self):
        return self._DECIMALS.get(self.currency, 2)

    # ------------------------------------------------------------------ #
    # representation
    # ------------------------------------------------------------------ #
    def __repr__(self):
        return "Money(%r, %r)" % (self._normalized(), self.currency)

    def __str__(self):
        amount = self._normalized()
        if self.currency:
            return "%s %s" % (amount, self.currency)
        return str(amount)

    def _normalized(self):
        """Amount rounded to the currency's minor units, as a plain number."""
        quant = Decimal(1).scaleb(-self._decimals())
        rounded = self.amount.quantize(quant)
        # Return a float for the common two-decimal case so that ``str`` and
        # ``repr`` are friendly, but keep exactness through Decimal equality.
        return rounded

    # ------------------------------------------------------------------ #
    # equality / hashing / ordering
    # ------------------------------------------------------------------ #
    def _coerce(self, other):
        if isinstance(other, Money):
            return other
        return None

    def __eq__(self, other):
        other = self._coerce(other)
        if other is None:
            return NotImplemented
        if self.currency != other.currency:
            return False
        return self._normalized() == other._normalized()

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __hash__(self):
        return hash((self._normalized(), self.currency))

    def _check_same_currency(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        if self.currency != other.currency:
            raise CurrencyMismatch(
                "cannot combine %r and %r" % (self.currency, other.currency)
            )
        return other

    def _compare(self, other, op):
        other = self._check_same_currency(other)
        if other is NotImplemented:
            return NotImplemented
        return op(self._normalized(), other._normalized())

    def __lt__(self, other):
        return self._compare(other, lambda a, b: a < b)

    def __le__(self, other):
        return self._compare(other, lambda a, b: a <= b)

    def __gt__(self, other):
        return self._compare(other, lambda a, b: a > b)

    def __ge__(self, other):
        return self._compare(other, lambda a, b: a >= b)

    # ------------------------------------------------------------------ #
    # arithmetic
    # ------------------------------------------------------------------ #
    def __add__(self, other):
        other = self._check_same_currency(other)
        if other is NotImplemented:
            return NotImplemented
        return Money(self.amount + other.amount, self.currency)

    __radd__ = __add__

    def __sub__(self, other):
        other = self._check_same_currency(other)
        if other is NotImplemented:
            return NotImplemented
        return Money(self.amount - other.amount, self.currency)

    def __neg__(self):
        return Money(-self.amount, self.currency)

    def __pos__(self):
        return Money(self.amount, self.currency)

    def __abs__(self):
        return Money(abs(self.amount), self.currency)

    def __mul__(self, factor):
        return Money(self.amount * self._to_decimal(factor), self.currency)

    __rmul__ = __mul__

    def __truediv__(self, divisor):
        if isinstance(divisor, Money):
            # Dividing by another money value yields a plain ratio.
            if self.currency != divisor.currency:
                raise CurrencyMismatch(
                    "cannot divide %r by %r"
                    % (self.currency, divisor.currency)
                )
            return self.amount / divisor.amount
        return Money(self.amount / self._to_decimal(divisor), self.currency)

    def __floordiv__(self, divisor):
        return Money(self.amount // self._to_decimal(divisor), self.currency)

    # Traditional money-library spellings -------------------------------
    def plus(self, other):
        return self + other

    def minus(self, other):
        return self - other

    def times(self, factor):
        return self * factor

    # ------------------------------------------------------------------ #
    # misc conveniences
    # ------------------------------------------------------------------ #
    @property
    def cents(self):
        """Amount expressed in the currency's minor units (an int)."""
        return int(self._normalized().scaleb(self._decimals()))

    def is_zero(self):
        return self._normalized() == 0

    def allocate(self, ratios):
        """Split this amount across ``ratios`` without losing a minor unit."""
        total = sum(ratios)
        if total <= 0:
            raise ValueError("ratios must sum to a positive value")
        minor = self._normalized().scaleb(self._decimals())
        remainder = int(minor)
        shares = []
        for ratio in ratios:
            share = int(minor * ratio / total)
            shares.append(share)
            remainder -= share
        # Hand the leftover minor units out one at a time.
        for index in range(remainder):
            shares[index % len(shares)] += 1
        quant = Decimal(1).scaleb(-self._decimals())
        return [
            Money(Decimal(share).scaleb(-self._decimals()).quantize(quant), self.currency)
            for share in shares
        ]

    def convert(self, rate, currency):
        """Return a new Money in ``currency`` using the given exchange rate."""
        return Money(self.amount * self._to_decimal(rate), currency)
